/// Computes the absolute value of a 32-bit signed integer.
///
/// Assumption (per problem statement): `x != i32::MIN`, so `-x` will not overflow.
fn abs(x: i32) -> i32 {
    debug_assert!(x != i32::MIN, "abs(i32::MIN) would overflow i32");
    if x >= 0 { x } else { -x }
}

fn main() {
    // Simple sanity checks
    assert_eq!(abs(0), 0);
    assert_eq!(abs(5), 5);
    assert_eq!(abs(-5), 5);

    // Example usage
    let x = -123;
    let result = abs(x);
    println!("{result}");
}